import {CARDS,cardById,STAGES,stageById,VERSION,DIAS} from './content.js';
import {clone,hash,random} from './engine.js';
export const SAVE_KEY='sslw-preservation-v1';
export function freshProfile(){return{format:1,rules:VERSION,id:globalThis.crypto?.randomUUID?.()||`local-${Date.now()}`,mode:'archive',mana:500,gems:100,owned:Object.fromEntries(CARDS.filter(c=>c.rarity==='HERO').map(c=>[c.id,{level:1,copies:1}])),deck:CARDS.filter(c=>c.rarity==='HERO').map(c=>c.id),dia:null,dias:[],clears:{},battleSeq:0,claimed:[],rng:87654231,pending:null,lastReplay:null,settings:{sound:false,reducedMotion:false},mySentai:'Archive squad'};}
const int=(x,max=100000000)=>Number.isSafeInteger(x)&&x>=0&&x<=max;
export function validateProfile(p){
 if(!p||p.format!==1||p.rules!==VERSION)throw Error('This save format or rules version is not supported.');
 if(typeof p.id!=='string'||p.id.length>100||!['classic','archive'].includes(p.mode)||!int(p.mana)||!int(p.gems)||!int(p.battleSeq)||!int(p.rng,4294967295))throw Error('Invalid profile values.');
 if(!p.owned||typeof p.owned!=='object'||Object.entries(p.owned).some(([id,v])=>!cardById(id)||!v||!int(v.level,5)||v.level<1||!int(v.copies)||v.copies<1))throw Error('Invalid collection.');
 if(!Array.isArray(p.deck)||p.deck.length>20||new Set(p.deck).size!==p.deck.length||p.deck.some(id=>!p.owned[id]))throw Error('Invalid deck.');
 if(!Array.isArray(p.dias)||p.dias.some(id=>!DIAS.find(d=>d.id===id))||(p.dia!==null&&!p.dias.includes(p.dia)))throw Error('Invalid Dia.');
 if(!p.clears||Object.entries(p.clears).some(([id,v])=>!stageById(id)||!int(v.count)||!int(v.bestTicks)))throw Error('Invalid stage progress.');
 if(!Array.isArray(p.claimed)||p.claimed.length>100000||p.claimed.some(x=>typeof x!=='string'||x.length>150))throw Error('Invalid transaction ledger.');
 if(typeof p.mySentai!=='string'||p.mySentai.length>32||!p.settings||typeof p.settings.sound!=='boolean'||typeof p.settings.reducedMotion!=='boolean')throw Error('Invalid settings.');
 for(const r of [p.pending,p.lastReplay])if(r){if(r.version!==VERSION||!r.config||!stageById(r.config.stage)||!Array.isArray(r.commands)||r.commands.length>10000||!int(r.endTick,20000)||typeof r.stateHash!=='string')throw Error('Invalid battle record.');if(r.config.deck.length!==20||r.config.deck.some(id=>!cardById(id))||!r.config.levels||Object.values(r.config.levels).some(l=>!int(l,5)||l<1)||!int(r.config.seed,4294967295))throw Error('Invalid battle configuration.');}
 return p;
}
export function saveProfile(p){validateProfile(p);const payload=JSON.stringify(p);const previous=localStorage.getItem(SAVE_KEY);if(previous)localStorage.setItem(SAVE_KEY+'-backup',previous);localStorage.setItem(SAVE_KEY,JSON.stringify({payload,checksum:hash(payload)}));}
export function parseSave(text){if(text.length>5000000)throw Error('This file is too large.');let o;try{o=JSON.parse(text)}catch{throw Error('This is not valid save JSON.')}if(typeof o.payload!=='string'||hash(o.payload)!==o.checksum)throw Error('The save checksum does not match.');return validateProfile(JSON.parse(o.payload))}
export function exportSave(p){validateProfile(p);const payload=JSON.stringify(p);return JSON.stringify({title:'Legend Wars Preservation save',payload,checksum:hash(payload)},null,2)}
export function loadProfile(){const raw=localStorage.getItem(SAVE_KEY);if(!raw)return{profile:freshProfile(),warning:null};try{return{profile:parseSave(raw),warning:null}}catch{const backup=localStorage.getItem(SAVE_KEY+'-backup');if(backup)try{return{profile:parseSave(backup),warning:'Recovered your previous save. The latest copy could not be read.'}}catch{}return{profile:null,warning:'Stored saves could not be read. Export the recovery data before starting a new profile.'}}}
export function upgrade(p,id){const o=p.owned[id];if(!o)throw Error('Card not owned.');if(o.level>=5)throw Error('Maximum reconstruction level reached.');const cost=o.level*100;if(p.mana<cost)throw Error(`You need ${cost} Mana.`);p.mana-=cost;o.level++;return cost}
export function recruit(p){if(p.gems<50)throw Error('You need 50 V-Gems. Earn them from missions.');p.gems-=50;const rare=random(p,100)<25,pool=CARDS.filter(c=>(c.rarity==='LEGEND')===rare),c=pool[random(p,pool.length)];if(p.owned[c.id]){p.owned[c.id].copies++;p.mana+=60}else p.owned[c.id]={level:1,copies:1};return c}
export function reward(p,record,result){const id=record.config.battleId;if(p.claimed.includes(id))return false;p.claimed.push(id);p.pending=null;p.lastReplay=clone(record);if(result==='victory'){const st=stageById(record.config.stage);p.mana+=st.reward;p.gems+=st.gems;const old=p.clears[st.id];p.clears[st.id]={count:(old?.count||0)+1,bestTicks:Math.min(old?.bestTicks??Infinity,record.endTick)}}return true}
export function battleConfig(p,stage){if(p.deck.length!==20)throw Error('Your deck needs exactly 20 cards.');const st=stageById(stage);if(!st)throw Error('Unknown mission');if(p.mode==='classic'&&st.unlockedBy&&!p.clears[st.unlockedBy])throw Error('Complete the previous chapter first.');p.battleSeq++;return{stage,seed:(random(p,4294967295)||1),deck:[...p.deck],levels:Object.fromEntries(Object.entries(p.owned).map(([id,v])=>[id,v.level])),dia:p.dia,battleId:`${p.id}:${p.battleSeq}`}}
